// Тикет #6a86f7e6. Опора: решение владелицы 30.09 (своя ссылка у вошедшего), ответ f83e1e3; F-99 AC1 (без согласия никто не добавляется).
// Ссылка приглашения открывается в приложении только через deep link (APP_SCHEME); без него тест пропускается.
// localStorage-трюк web (чистое «pending-invite») не переносим — в приложении состояние в AsyncStorage; первый прогон — калибровка.
import { byText, byTextContains, tapText, scrollToText } from '../../helpers/ui.ts';
import { goTab, hasDeepLinks, openRoute } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';

describe('«מפת השפעה» и приглашение', () => {
  afterEach(async () => { await toHome(); });

  it('IM-03 Своя ссылка приглашения у вошедшего → «זה קישור ההזמנה שלך…» #6a86f7e6 @prod-safe', async function () {
    if (!hasDeepLinks()) this.skip();
    // 1. Открыть свою ссылку приглашения.
    await openRoute('/?invite=c750744f-6d79-4dd5-a891-0b3446eb08cd');
    await (await byTextContains('זה קישור ההזמנה שלך. אפשר לשלוח אותו למי שרוצה להתחזק איתך.')).waitForDisplayed({ timeout: 20000 });

    // 2. «המסע שלי» → «מפת השפעה» по-прежнему «2 אנשים».
    await goTab('המסע שלי');
    await (await byText('המסע שלי')).waitForDisplayed({ timeout: 20000 });
    const w = await byTextContains('עלית דרגה');
    if (await w.waitForDisplayed({ timeout: 1500 }).then(() => true, () => false)) await tapText('סגירה');
    await scrollToText('מפת השפעה');
    await scrollToText('2 אנשים');
  });
});
